solution.solution.cpp:
#include <string>
#include <utility>
#include <vector>

void addName(std::vector<std::string>& names, std::string name)
{
    names.push_back(std::move(name));
}

unitTests:
TEST("adds the name") { std::vector<std::string> v; addName(v, "Ada"); addName(v, "Bo"); CHECK_EQ(v, (std::vector<std::string>{ "Ada", "Bo" })); }
TEST("the string's buffer is moved, not copied") {
    std::vector<std::string> v;
    v.reserve(4);
    std::string longName(200, 'x');
    const char* buffer{ longName.data() };
    addName(v, std::move(longName));
    CHECK(v.back().data() == buffer);
    CHECK_EQ(v.back().size(), 200u);
}

